const _ = require('lodash');
const constant = require('../lib/constant');

/**
 * extend.js:
 * mget2obj key [key ...]
 * mhgetall key [key ...]
 * mhgetall2obj key [key ...]
 * zrangebyscore2map key min max [WITHSCORES] [LIMIT offset count]
 * zrevrangebyscore2map key max min [WITHSCORES] [LIMIT offset count]
 * lock key [millisecond](default is 10s)
 * getWithVer key
 * mgetWithVer key [key ...]
 * mgetWithVer2Obj key [key ...]
 * zrangebyscoreWithTotal key min max [WITHSCORES] [LIMIT offset count]
 * zrevrangebyscoreWithTotal key min max [WITHSCORES] [LIMIT offset count]
 * zrangebyscore2mapWithTotal key min max [WITHSCORES] [LIMIT offset count]
 * zrevrangebyscore2mapWithTotal key min max [WITHSCORES] [LIMIT offset count]
 * setChanged key value
 */
module.exports = (common) => {
  const operations = {

    * lock(key, millisecond) {
      return yield common.lock(key, millisecond);
    },

    * mget2obj(...keys) {
      /* istanbul ignore if */
      if (keys === null || keys === undefined || keys.length === 0) {
        return {};
      }
      // forceMaster
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      if (keys.length === 1) {
        const key = keys[0];
        if (_.isString(key)) {
          const result = {};
          const value = yield common.getValue(key, constant.TYPE.STRING, forceMaster);
          if (value === undefined) {
            return undefined;
          }
          result[key] = value;
          return result;
        } else if (_.isArray(key)) {
          if (key.length === 1) {
            const result = {};
            const value = yield common.getValue(key[0], constant.TYPE.STRING, forceMaster);
            if (value === undefined) {
              return undefined;
            }
            result[key[0]] = value;
            return result;
          }
          keys = key;
        } else {
          /* istanbul ignore next */
          return {};
        }
      }
      return yield common.getBatch2Obj(keys, false, forceMaster);
    },

    * mhgetall(...keys) {
      /* istanbul ignore if */
      if (keys === null || keys === undefined || keys.length === 0) {
        return [];
      }
      // forceMaster
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      if (keys.length === 1) {
        const key = keys[0];
        if (_.isString(key)) {
          const value = yield common.getValue(key, constant.TYPE.HASH, forceMaster);
          if (value === undefined) {
            return undefined;
          }
          return [ value ];
        } else if (_.isArray(key)) {
          keys = keys[0];
        } else {
          /* istanbul ignore next */
          return [];
        }
      }
      return yield common.getBatch(keys, false, false, forceMaster);
    },

    * mhgetall2obj(...keys) {
      /* istanbul ignore if */
      if (keys === null || keys === undefined || keys.length === 0) {
        return {};
      }
      // forceMaster
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      if (keys.length === 1) {
        const key = keys[0];
        if (_.isString(key)) {
          const result = {};
          const value = yield common.getValue(key, constant.TYPE.HASH, forceMaster);
          if (value === undefined) {
            return undefined;
          }
          result[key] = value;
          return result;
        } else if (_.isArray(key)) {
          if (key.length === 1) {
            const result = {};
            const value = yield common.getValue(key[0], constant.TYPE.HASH, forceMaster);
            if (value === undefined) {
              return undefined;
            }
            result[key[0]] = value;
            return result;
          }
          keys = key;
        } else {
          /* istanbul ignore next */
          return {};
        }
      }
      return yield common.getBatch2Obj(keys, false, forceMaster);
    },

    // eslint-disable-next-line no-unused-vars
    * zrangebyscore2map(key) {
      const ret = yield common.zrangebyscoreWithTotal(...arguments);
      if (ret === undefined) {
        return undefined;
      }
      return common.arrayToMap(ret.data);
    },

    // eslint-disable-next-line no-unused-vars
    * zrevrangebyscore2map(key) {
      const ret = yield common.zrevrangebyscoreWithTotal(...arguments);
      if (ret === undefined) {
        return undefined;
      }
      return common.arrayToMap(ret.data);
    },

    * getWithVer(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return null;
      }
      const valueWithVer = yield common.getValueWithVer(key, constant.TYPE.STRING, forceMaster);
      if (valueWithVer === undefined) {
        return valueWithVer;
      }
      if (valueWithVer.ver === 1 && valueWithVer.value === null) {
        return null;
      }
      return valueWithVer;
    },

    * setWithVer(key, value, ver) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined || ver === null || ver === undefined) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const ret = yield common.setStringEx(key, common.toStringWithType(value, constant.TYPE.STRING), ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * mgetWithVer(...keys) {
      /* istanbul ignore if */
      if (keys === null || keys === undefined || keys.length === 0) {
        return [];
      }
      // forceMaster
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      if (keys.length === 1) {
        const key = keys[0];
        if (_.isString(key)) {
          const ret = yield common.getValueWithVer(key, constant.TYPE.STRING, forceMaster);
          if (ret === undefined) {
            return undefined;
          }
          return [ ret ];
        } else if (_.isArray(key)) {
          if (key.length === 1) {
            const ret = yield common.getValueWithVer(key[0], constant.TYPE.STRING, forceMaster);
            if (ret === undefined) {
              return undefined;
            }
            return [ ret ];
          }
          keys = key;
        } else {
          /* istanbul ignore next */
          return [];
        }
      }
      return yield common.getBatch(keys, true, false, forceMaster);
    },

    * mgetWithVer2Obj(...keys) {
      /* istanbul ignore if */
      if (keys === null || keys === undefined || keys.length === 0) {
        return {};
      }
      // forceMaster
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      if (keys.length === 1) {
        const key = keys[0];
        if (_.isString(key)) {
          const result = {};
          const value = yield common.getValueWithVer(key, constant.TYPE.STRING, forceMaster);
          if (value === undefined) {
            return undefined;
          }
          result[key] = value;
          return result;
        } else if (_.isArray(key)) {
          if (key.length === 1) {
            const result = {};
            const value = yield common.getValueWithVer(key[0], constant.TYPE.STRING, forceMaster);
            if (value === undefined) {
              return undefined;
            }
            result[key[0]] = value;
            return result;
          }
          keys = key;
        } else {
          /* istanbul ignore next */
          return {};
        }
      }
      return yield common.getBatch2Obj(keys, true, forceMaster);
    },

    zrangebyscoreWithTotal: common.zrangebyscoreWithTotal,

    zrevrangebyscoreWithTotal: common.zrevrangebyscoreWithTotal,

    // eslint-disable-next-line no-unused-vars
    zrangebyscore2mapWithTotal: function* (key) {
      const dataWithTotal = yield common.zrangebyscoreWithTotal(...arguments);
      if (dataWithTotal === undefined) {
        return undefined;
      }
      return { data: common.arrayToMap(dataWithTotal.data), total: dataWithTotal.total };
    },

    // eslint-disable-next-line no-unused-vars
    zrevrangebyscore2mapWithTotal: function* (key) {
      const dataWithTotal = yield common.zrevrangebyscoreWithTotal(...arguments);
      if (dataWithTotal === undefined) {
        return undefined;
      }
      return { data: common.arrayToMap(dataWithTotal.data), total: dataWithTotal.total };
    },

    setChanged: function* (key, value) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return false;
      }
      const obj = yield common.getValue(key, constant.TYPE.STRING, constant.CONSTANT.FORCEMASTER);
      if (obj === undefined) {
        return undefined;
      }
      if (_.isEqual(obj, value)) {
        return true;
      }
      return yield common.setString(key, common.toStringWithType(value, constant.TYPE.STRING));
    },

  };
  return operations;
};
